import * as THREE from "three";
import { FBXLoader } from "three/examples/jsm/loaders/FBXLoader.js";

export const getDirectionalLight = (
  scene,
  x: number = -100,
  y: number = -100,
  z: number = 100
) => {
  const light = new THREE.DirectionalLight(0xffffff, 10);
  light.position.set(x, y, z);
  light.castShadow = true;
  light.shadow.bias = -0.00001;
  light.shadow.mapSize.width = 2048;
  light.shadow.mapSize.height = 2048;
  light.shadow.camera.near = 0.5;
  light.shadow.camera.far = 5000;
  light.shadow.camera.left = -50;
  light.shadow.camera.right = 50;
  light.shadow.camera.top = 50;
  light.shadow.camera.bottom = -50;
  scene.add(light);
  return light;
};

export const createStudioEnvironment = (scene) => {
  const geometry = new THREE.SphereGeometry(1000, 32, 16);
  const material = new THREE.ShaderMaterial({
    uniforms: {
      topColor: { value: new THREE.Color(0xffffff) },
      bottomColor: { value: new THREE.Color(0xf7f7f7) },
      offset: { value: 1.4 },
      exponent: { value: 1.4 },
    },
    vertexShader: `
      varying vec3 vWorldPosition;
      void main() {
          vec4 worldPosition = modelMatrix * vec4(position, 1.0);
          vWorldPosition = worldPosition.xyz;
          gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
      }
      `,
    fragmentShader: `
      uniform vec3 topColor;
      uniform vec3 bottomColor;
      uniform float offset;
      uniform float exponent;
      varying vec3 vWorldPosition;
      void main() {
          float h = normalize(vWorldPosition + offset).z;
          gl_FragColor = vec4(mix(bottomColor, topColor, max(pow(max(h, 0.0), exponent), 0.0)), 1.0);
      }
      `,
    side: THREE.BackSide,
  });

  const mesh = new THREE.Mesh(geometry, material);
  scene.add(mesh);

  return scene;
};

export const loadFBX = (pathFile: string): Promise<THREE.Group> => {
  const scaleFactor = 0.01;
  const loader = new FBXLoader();

  return new Promise((resolve, reject) => {
    loader.load(
      pathFile,
      (fbx) => {
        fbx.castShadow = true;
        fbx.receiveShadow = true;
        fbx.rotation.x = Math.PI / 2;

        fbx.traverse((child) => {
          if (child.isMesh) {
            child.castShadow = true;
            child.receiveShadow = true;

            const material = child.material;

            if (Array.isArray(material)) {
              child.material = material.map(
                (mat) =>
                  // new THREE.MeshStandardMaterial({
                  new THREE.MeshPhysicalMaterial({
                    map: mat.map ?? null,
                    color: mat.color ?? new THREE.Color(0xffffff),
                    normalMap: mat.normalMap ?? null,
                    metalness: 0.1,
                    roughness: 0.8,
                  })
              );
            } else {
              child.material = new THREE.MeshPhysicalMaterial({
                map: material.map ?? null,
                color: material.color ?? new THREE.Color(0xffffff),
                // color:  new THREE.Color(0x444444), // material.color ?? new THREE.Color(0xffffff),
                normalMap: material.normalMap ?? null,
                metalness: 0.2,
                roughness: 0.5,
              });
            }
          }
        });

        fbx.scale.set(scaleFactor, scaleFactor, scaleFactor);
        resolve(fbx);
      },
      undefined,
      (error) => {
        reject(error);
      }
    );
  });
};
