import * as THREE from "three";
import { OrbitControls } from "three-orbitcontrols-ts";
import { ThreeCore } from "../";

export class CameraWrapper {
  public core: ThreeCore;
  public controls: OrbitControls;
  public camera: THREE.PerspectiveCamera;

  public cameraTargetStartVec = new THREE.Vector3(0, -2000, 0);
  public cameraTargetEndVec = new THREE.Vector3(0, -150, 0);
  
  public startTime = null;
  public duration = 1000;
  public t = 0.0;

  constructor(core: ThreeCore) {
    this.core = core;
    this.camera = new THREE.PerspectiveCamera(
      30,
      this.core.host.clientWidth / this.core.host.clientHeight,
      3,
      3000
    );
    this.controls = new OrbitControls(
      this.camera,
      this.core.renderer.domElement
    );

    this.camera.position.set(this.cameraTargetStartVec.x, this.cameraTargetStartVec.y, this.cameraTargetStartVec.z);
    this.camera.up.set(0, 0, 1);
    this.controls.minPolarAngle = 0; // 위쪽 제한 (0: 위에서 내려다봄)
    this.controls.maxPolarAngle = Math.PI / 2; // 아래쪽 제한 (PI/2: 수평)
    this.controls.update();

  }
  public onWindowResize() {
    this.camera.aspect =
      this.core.host.clientWidth / this.core.host.clientHeight;
    this.camera.updateProjectionMatrix();
  }
  public update() {
    this.controls.update();
    this.cameraAni();
    this.t += 0.01;
  }
  public move(x: number, y: number, z: number) {
    this.cameraTargetStartVec.x = this.camera.position.x;
    this.cameraTargetStartVec.y = this.camera.position.y;
    this.cameraTargetStartVec.z = this.camera.position.z;
    this.cameraTargetEndVec.x = x;
    this.cameraTargetEndVec.y = y;
    this.cameraTargetEndVec.z = z;
    this.t = 0.0;
    this.startTime = undefined;
  }
  public cameraAni() {
    if (this.t < 1) {
      const time = performance.now();

      if (!this.startTime) this.startTime = time;
      // console.log(time, this.t)

      const elapsed = time - this.startTime;
      const t = Math.min(elapsed / this.duration, 1); // 0~1 사이로 clamp
      const easeOut = 1 - Math.pow(1 - t, 5); // cubic easing out

      this.camera.position.y =
        this.cameraTargetStartVec.y +
        (this.cameraTargetEndVec.y - this.cameraTargetStartVec.y) * easeOut;
      this.camera.position.x =
        this.cameraTargetStartVec.x +
        (this.cameraTargetEndVec.x - this.cameraTargetStartVec.x) * easeOut;
      this.camera.position.z =
        this.cameraTargetStartVec.z +
        (this.cameraTargetEndVec.z - this.cameraTargetStartVec.z) * easeOut;
    }
  }
}
