import { Solution } from '../'

export class View {
    solution: Solution
    sampleCameraPosition = [
        [100, -100, 100],
        [100, 100, 100],
        [0, -100, 50],
        [0, -100, 0],
        [0, 0, 100]
    ]
    index = 0;
    constructor(solution: Solution) {
        this.solution = solution;
        this.initUI();
        // console.log('ui loading');
    }
    public initUI() {
        const div = document.createElement('div');
        div.style.width = '100px';
        div.style.height = '100px';
        div.style.background = '#fefefe';
        div.style.position = 'absolute';
        div.style.zIndex = '10';

        this.solution.core.threeCore.host.appendChild(div);
        // this.solution.core.threeCore.host.style.position = 'absolute';
        this.solution.core.threeCore.renderer.domElement.style.position = 'absolute';

        const divBt = document.createElement('div')
        div.appendChild(divBt);
        divBt.textContent = 'changing views'
        divBt.onclick = () => {
            const vec = this.sampleCameraPosition[ this.index++ % this.sampleCameraPosition.length ]
            // console.log('btn', this.index % this.sampleCameraPosition.length)
            this.solution.threeCore.cameraWrapper.move(vec[0], vec[1], vec[2]);
        }

    }
}