import * as THREE from "three";

import { ThreeCore } from "../ThreeCore";
import { loadFBX, createStudioEnvironment } from "../Utili";

export class Core {
  public threeCore: ThreeCore;
  public boxMeshes: THREE.Mesh[] = [];


  meshDoorLeft: THREE.Mesh = undefined
  meshDoorRight: THREE.Mesh = undefined

  constructor(threeCore: ThreeCore, sphereNeeded = false) {
    this.threeCore = threeCore;

    this.init();
  }
  public init() {
    const planeGeometry = new THREE.PlaneGeometry(500, 500);
    const planeMaterial = new THREE.MeshStandardMaterial({
      color: 0xcecece,
      // color: 0xa4a4a4,
      roughness: 0.8,
      metalness: 0.8,
    });

    const planeGround = new THREE.Mesh(planeGeometry, planeMaterial);
    planeGround.receiveShadow = true;
    planeGround.position.z = -18;
    this.threeCore.scene.add(planeGround);

    const files = [
      "onlyaCube-clean-static.fbx",
      "solarPanel.fbx",
      "door-B-1.fbx",
      "door-B-2.fbx",
    ];
    this.loadAllModels(files);

    createStudioEnvironment(this.threeCore.scene);
  }
  public loadAllModels = async (files) => {
    try {
      const loadPromises = files.map((file) =>
        loadFBX(process.env.PUBLIC_URL + "/static/data/model/" + file)
      );

      const fbxModels = await Promise.all(loadPromises);

      fbxModels.forEach((fbx) => {
        this.threeCore.scene.add(fbx);
      });

      this.threeCore.loaded = true;
    } catch (error) {
      // console.error("fail to load :", error);
    }
  };
  public update() {
    // console.log('update...');





  }
  public mouseDown(e: MouseEvent) {
    const mesh = onClick(this, e)
    console.log(mesh.name, e, "core");
    if (mesh.name === 'mesh11848' || mesh.name === 'Object991' ) {
      mesh.position.y += 100
    }
    
  }
  public mouseUp(e: MouseEvent) {
    // console.log(e, 'core');
  }
  public mouseMove(e: MouseEvent) {
    // console.log(e, 'core');
  }
  public mouseDrag(e: MouseEvent) {
    // console.log(e, 'core');
  }
  public destroy() {}
}

const onClick = (core: Core, event) => {
  const raycaster = new THREE.Raycaster();
  const mouse = new THREE.Vector2();

  mouse.x = (event.clientX / window.innerWidth) * 2 - 1;
  mouse.y = -(event.clientY / window.innerHeight) * 2 + 1;

  raycaster.setFromCamera(mouse, core.threeCore.cameraWrapper.camera);

  const intersects = raycaster.intersectObjects(core.threeCore.scene.children, true);

  if (intersects.length > 0) {
    const selectedObject = intersects[0].object;
    console.log("Selected object:", selectedObject);

    console.log("Name:", selectedObject.name);
    console.log("position:", selectedObject.position);
    console.log("scale:", selectedObject.scale);
    console.log("Material:", selectedObject.material);
    // selectedObject.position.y += 100;
    // 필요하면 추가 처리 가능
    return selectedObject;
  } else {
    // console.log("아무 오브젝트도 선택되지 않았습니다.");
  }
};
